#!/system/bin/sh
P=com.omarea.vtools;T=/data/local/tmp/scene-adb-stage;D=$T/daemon;B=$T/toolkit/busybox;Q=$T/binder.so;X=/data/local/tmp/scene-daemon;Y=/data/local/tmp/toolkit/busybox;K=/data/local/tmp/toolkit;mkdir -p "$K";export PATH="$PATH:$K";cp "$D" "$X"||exit 1;chmod 777 "$X"||exit 1;cp "$B" "$Y"||exit 1;chmod 777 "$Y"||exit 1;cd "$K"||exit 1;[ -x ./busybox ]||exit 1;for a in $(./busybox --list);do case "$a" in sh|busybox|shell|swapon|swapoff|mkswap) :;;*) ./busybox ln -sf busybox "$a" >/dev/null 2>&1;;esac;done;./busybox ln -sf busybox busybox_1_30_1 >/dev/null 2>&1;[ -f "$Q" ]&&cp -f "$Q" /data/local/tmp/binder.so;nohup "$X" >/dev/null 2>&1 & sleep 1;[ "$(pgrep scene-daemon)" != "" ]||exit 1;[ "$SCENE_SKIP_START" != 1 ]&&am start -n "$P/.activities.ActivityStartSplash" -f 0x10008000 >/dev/null 2>&1;cmd package compile -m speed "$P" >/dev/null 2>&1 &;dumpsys deviceidle whitelist +"$P" >/dev/null 2>&1;cmd appops set "$P" RUN_IN_BACKGROUND allow >/dev/null 2>&1;cmd appops set "$P" RUN_ANY_IN_BACKGROUND allow >/dev/null 2>&1;am set-standby-bucket "$P" active >/dev/null 2>&1;am set-inactive --user 0 "$P" false >/dev/null 2>&1;am set-bg-restriction-level --user 0 "$P" unrestricted >/dev/null 2>&1;am set-foreground-service-delegate --user 0 "$P" start >/dev/null 2>&1;am unfreeze --sticky "$P" >/dev/null 2>&1;exit 0
